#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(grid);library(ggtext);library(ggsignif);library(ggridges);library(ggrepel);library(circlize);library(ComplexHeatmap)})
root<-normalizePath('.');fd<-file.path(root,'results/figures');dd<-file.path(root,'results/plot_data');dir.create(fd,recursive=T,showWarnings=F);dir.create(dd,recursive=T,showWarnings=F)
set.seed(20260922);sv<-function(n,p,w,h)ggsave(file.path(fd,n),p,width=w,height=h,dpi=220,bg='white');wd<-function(n,x)write.csv(x,file.path(dd,n),row.names=F)
dark<-theme(axis.line=element_line(colour='#222',linewidth=.6),axis.ticks=element_line(colour='#222',linewidth=.5))
# 46 gradient violin
G<-c('Very ancient','Ancient','Recent/very recent');P<-list(c(.79,.84,.76,.88),c(.15,.13,.10,.18),c(.055,.03,0,.08));C<-c('#0EACC9','#A184BC','#E57164');B<-list(c('white','#B1D8E7'),c('white','#BFA0CC'),c('white','#F7B78B'))
d46<-do.call(rbind,lapply(1:3,function(i)data.frame(age=G[i],type=rep(c('Reference','Specialized\nfor diapause'),each=100),value=c(rnorm(100,P[[i]][1],.005),rnorm(100,P[[i]][2],.005)))));for(i in 1:3){ix<-d46$age==G[i];d46$value[ix]<-pmin(P[[i]][4]-.0005,pmax(P[[i]][3]+.0005,d46$value[ix]))}
pl<-lapply(1:3,function(i){z<-subset(d46,age==G[i]);lim<-P[[i]][3:4];gr<-rasterGrob(colorRampPalette(B[[i]])(256),width=unit(1,'npc'),height=unit(1,'npc'),interpolate=T);ggplot(z,aes(type,value,fill=type))+annotation_custom(gr,-Inf,Inf,-Inf,Inf)+geom_violin(trim=F,colour='#222',linewidth=.65)+stat_summary(fun.data=function(x)data.frame(y=mean(x),ymin=mean(x)-sd(x),ymax=mean(x)+sd(x)),geom='crossbar',width=.28,linewidth=.45)+annotate('text',1.5,lim[2]-.009,label=c('italic(P) == 2.6e-34','italic(P) == 7.8e-34','italic(P) == 2.9e-34')[i],parse=T,size=3.5)+scale_fill_manual(values=c('#9C9C9C',C[i]))+scale_y_continuous(limits=lim,expand=c(0,0))+labs(title=c('Very ancient<br>(> 473 mya)','Ancient<br>(111–473 mya)','Recent/very recent<br>(0–111 mya)')[i],x=NULL,y='Fraction of total paralogs')+theme_classic(base_size=10)+dark+theme(legend.position='none',axis.text.x=element_text(angle=45,hjust=1,colour='black'),plot.title=element_textbox_simple(fill=C[i],colour='white',halign=.5,size=9,padding=margin(4,1,4,1),margin=margin(0,0,7,0)))})
suppressWarnings(sv('46_gradient_violin.png',wrap_plots(pl,nrow=1),8,6));wd('46_gradient_violin.csv',d46)
# 47 ridges
T47<-c('LT-ILC1','CD49a+trNK','CD49a-trNK','cNK','cILC1','ILC2','ILC3');F47<-c('IFN-γ','IL2','TNF-α','GM-CSF');d47<-expand.grid(factor=F47,type=T47,response=c('+','-'),rep=1:90);d47$value<-rlnorm(nrow(d47),8+as.numeric(factor(d47$type))*.13+as.numeric(factor(d47$factor))*.08+(d47$response=='+')*.15,.25);d47$id<-factor(paste(d47$type,d47$response,sep='_'),levels=rev(as.vector(rbind(paste0(T47,'_+'),paste0(T47,'_-')))));pal<-setNames(rep(c('#ff00ff','#5600ac','#cc2e2d','#47DDE0','#4c4c4c','#61a4f9','#008100'),each=2),levels(d47$id))
p47<-ggplot(d47,aes(value,id,fill=id,colour=id,alpha=response))+geom_density_ridges(scale=1.35,linewidth=.35)+scale_x_log10()+scale_fill_manual(values=pal,guide='none')+scale_colour_manual(values=pal,guide='none')+scale_alpha_manual(values=c('+'=1,'-'=.22),guide='none')+scale_y_discrete(labels=function(x)sub('.*_','',x))+facet_wrap(~factor,nrow=1,scales='free_x',strip.position='bottom')+theme_bw(base_size=8)+theme(panel.border=element_rect(colour='#555',linewidth=.6),panel.grid=element_blank(),panel.spacing=unit(0,'mm'),axis.title=element_blank(),axis.text.y=element_text(face='bold',size=6.5),axis.ticks.y=element_blank(),strip.background=element_blank(),strip.text=element_text(face='bold',size=9))
ann47<-ggplot(data.frame(type=T47,y=1:7),aes(.5,y,label=type,colour=type))+annotate('rect',xmin=-Inf,xmax=Inf,ymin=-Inf,ymax=Inf,fill='black')+geom_text(fontface='bold',size=3.3)+scale_colour_manual(values=setNames(c('#ff00ff','#5600ac','#cc2e2d','#47DDE0','#4c4c4c','#61a4f9','#008100'),T47),guide='none')+xlim(0,1)+theme_void();p47<-p47+ann47+plot_layout(widths=c(5,.9));sv('47_faceted_ridgeline.png',p47,8,4.71);wd('47_faceted_ridgeline.csv',d47)
# 48 spectrum
x<-seq(670,850,length.out=175);fun<-function(x,a).85*exp(-((x-697)/9)^2)+a*exp(-((x-802)/13)^2);d48<-rbind(data.frame(wavelength=x,intensity=pmin(8.48,pmax(0,fun(x,7.5)+rnorm(175,0,.16))),group='400 nN'),data.frame(wavelength=x,intensity=pmin(8.48,pmax(0,fun(x,4.4)+rnorm(175,0,.13))),group='0 nN'));fit<-do.call(rbind,lapply(split(d48,d48$group),function(z){xx<-seq(min(z$wavelength),max(z$wavelength),length=700);data.frame(wavelength=xx,intensity=predict(smooth.spline(z$wavelength,z$intensity,spar=.45),xx)$y,group=z$group)}));p48<-ggplot(d48,aes(wavelength,intensity,colour=group))+geom_point(aes(fill=group),shape=21,size=1.25,stroke=.55)+geom_line(data=fit,linewidth=.85)+scale_colour_manual(values=c('400 nN'='#FF2400','0 nN'='#075ED1'))+scale_fill_manual(values=c('400 nN'='#FF9900','0 nN'='#66CCFF'),guide='none')+guides(colour=guide_legend(override.aes=list(shape=21,fill='white',size=2.6)))+scale_y_continuous(limits=c(0,8.5),expand=c(0,0),breaks=seq(0,8,2))+scale_x_continuous(expand=c(0,0))+labs(x='Wavelength (nm)',y='Normalized emission intensity',colour=NULL)+theme_classic(base_size=12)+dark+theme(legend.position=c(.22,.9))
sv('48_custom_smooth_spectrum.png',p48,7.11,8);wd('48_custom_smooth_spectrum.csv',d48)
# 49 line + bar
w<-0:11;dl<-expand.grid(week=w,treat=c('Control','Acox1-LKO'),rep=1:8);dl$value<-22+dl$week*1.9-(dl$treat=='Acox1-LKO')*(2+dl$week*.35)+rnorm(nrow(dl),0,1.5);db<-expand.grid(group=c('Fat','Lean'),treat=c('Control','Acox1-LKO'),rep=1:8);db$value<-with(db,ifelse(group=='Fat',ifelse(treat=='Control',19,14),ifelse(treat=='Control',21,22)))+rnorm(nrow(db),0,2)
pa<-ggplot(dl,aes(week,value,group=treat))+stat_summary(aes(colour=treat),fun.data=mean_se,geom='errorbar',width=.25,linewidth=.55)+stat_summary(aes(fill=treat,shape=treat),fun=mean,geom='point',size=2.5,colour='transparent')+stat_summary(fun=mean,geom='line',linewidth=.7)+scale_fill_manual(values=c(Control='black','Acox1-LKO'='red'))+scale_colour_manual(values=c(Control='black','Acox1-LKO'='black'))+scale_shape_manual(values=c(21,22))+labs(x='Weeks (HFD)',y='Body weight (g)',fill=NULL,shape=NULL,colour=NULL)+theme_classic(base_size=10)+dark+theme(legend.position=c(.16,.91))
pb<-ggplot(db,aes(group,value,colour=treat))+stat_summary(aes(group=treat),fun=mean,geom='bar',fill='white',position=position_dodge(.75),width=.65,linewidth=.75)+stat_summary(aes(group=treat),fun.data=mean_se,geom='errorbar',position=position_dodge(.75),width=.2,linewidth=.55)+geom_point(aes(fill=treat,shape=treat),position=position_jitterdodge(.12,.75),size=2,stroke=.7)+scale_colour_manual(values=c(Control='black','Acox1-LKO'='red'))+scale_fill_manual(values=c(Control='black','Acox1-LKO'='red'))+scale_shape_manual(values=c(21,22))+labs(x=NULL,y='Body composition (g)')+theme_classic(base_size=10)+dark+theme(legend.position='none')
sv('49_line_bar_combo.png',pa+pb+plot_layout(widths=c(2,1))+plot_annotation(tag_levels='a'),8,5);wd('49_line.csv',dl);wd('49_bar.csv',db)
# 50 diagonal + histogram
n<-82;d50<-data.frame(Control=rnorm(n,0,.38));d50$Treat<-d50$Control+rnorm(n,.06,.28);d50$group<-ifelse(abs(d50$Treat-d50$Control)>.35,'significant','insignificant');pink<-'#F71D53';pm<-ggplot(d50,aes(Control,Treat,fill=group))+geom_point(shape=24,size=3.4,stroke=1.15,colour=pink)+scale_fill_manual(values=c(insignificant='white',significant=pink))+geom_hline(yintercept=0,linetype='dashed',linewidth=.65)+geom_vline(xintercept=0,linetype='dashed',linewidth=.65)+geom_abline(linetype='dashed',linewidth=.65)+annotate('text',-.72,.93,label='p = 0.22',size=5)+coord_cartesian(xlim=c(-1,1),ylim=c(-1,1),clip='off')+labs(x='PES without Microstim.(°)',y='PES with Microstim.(°)')+theme_classic(base_size=13)+dark+theme(legend.position='none',plot.margin=margin(80,70,10,10));ph<-ggplot(d50,aes(Treat-Control,fill=group))+geom_histogram(bins=9,colour=pink,linewidth=.8)+geom_vline(xintercept=median(d50$Treat-d50$Control),linewidth=.65)+scale_fill_manual(values=c(insignificant='white',significant=pink))+theme_classic(base_size=8)+dark+theme(legend.position='none',axis.title=element_blank());g<-grobTree(ggplotGrob(ph),vp=viewport(width=.9,height=.7,angle=-45));suppressWarnings(sv('50_diagonal_scatter_hist.png',pm+inset_element(g,.67,.73,1.22,1.20,align_to='plot'),7.38,8));wd('50_diagonal_scatter_hist.csv',d50)
# 51 circular bars
gs<-c('Tinnitus characteristics','Physical quality of life','Experiences of pain','Somatic expressions','Affective symptoms','Tinnitus-related distress','Internal resources','Perceived stress','Mental quality of life');d51<-do.call(rbind,lapply(1:9,function(i){n<-c(9,8,8,10,9,10,8,8,8)[i];data.frame(group=gs[i],item=paste0('Q',i,'_',1:n),value=pmax(-1.45,pmin(1.5,rnorm(n,.08,.7))))}));d51$id<-1:nrow(d51);p51<-ggplot(d51,aes(id,value,fill=value))+geom_hline(yintercept=seq(-1.5,1.5,.5),colour='#666',linewidth=.3)+geom_col(width=.72,colour='white',linewidth=.18)+geom_text(aes(y=ifelse(value>=0,1.67,-1.67),label=item,angle=90-360*(id-.5)/nrow(d51),hjust=ifelse(90-360*(id-.5)/nrow(d51)< -90,1,0)),size=1.75,colour='#333')+scale_fill_gradient2(low='#2C70B7',mid='#FFF4C6',high='#F04B23',limits=c(-1.5,1.5),name='Patient\naverage')+scale_y_continuous(limits=c(-2.45,2))+coord_polar(clip='off')+annotate('text',median(d51$id),-2.15,label='Psychosomatic\ngroups',size=2.2)+theme_void()+theme(legend.position=c(.88,.88));sv('51_grouped_gradient_circular_bar.png',p51,8,8);f51<-file.path(fd,'51_grouped_gradient_circular_bar.png');im51<-magick::image_read(f51);im51<-magick::image_trim(im51,fuzz=5);im51<-magick::image_resize(im51,'1720x1720');im51<-magick::image_extent(im51,'1760x1760',gravity='center',color='white');magick::image_write(im51,f51);wd('51_grouped_gradient_circular_bar.csv',d51)
# 52 dot stack + pie
ids<-paste0('CRUKP',sample(100:999,24));ct<-sort(sample(3:32,24,T));d52<-do.call(rbind,lapply(1:24,function(i)data.frame(id=ids[i],seq=1:ct[i],group=sample(c('imaged + sampled','sampled only','imaged only'),ct[i],T,c(.5,.3,.2)))));d52$id<-factor(d52$id,levels=ids);co<-c('imaged + sampled'='#C8102E','sampled only'='#E6B794','imaged only'='white');main<-ggplot(d52,aes(id,seq,fill=group))+geom_point(shape=21,size=3.5,stroke=.7,colour='#222')+scale_fill_manual(values=co)+scale_y_continuous(limits=c(0,34),expand=c(0,0))+labs(x=NULL,y='Metastases')+theme_classic(base_size=9)+dark+theme(axis.text.x=element_text(angle=90,hjust=1),legend.position=c(.02,.98),legend.justification=c(0,1),legend.title=element_blank());pie<-as.data.frame(table(d52$group));names(pie)<-c('group','n');pp<-ggplot(pie,aes('',n,fill=group))+geom_col(width=1,colour='#222',linewidth=.75)+coord_polar('y')+geom_text(aes(label=n),position=position_stack(vjust=.5),size=4)+scale_fill_manual(values=co)+theme_void()+theme(legend.position='none');sv('52_stacked_dot_inset_pie.png',main+inset_element(pp,.3,.55,.78,.97),8,7.42);wd('52_stacked_dot_inset_pie.csv',d52)
# 53 circos tracks
n<-92;d53<-data.frame(id=sprintf('P%03d',1:n),age=sort(sample(20:78,n,T)),BMI=rnorm(n,27,4),sex=sample(c('Female','Male'),n,T),ethnicity=sample(c('Caucasian','Asian','Hispanic','Black'),n,T),IRIS=sample(c('IS','IR'),n,T));png(file.path(fd,'53_sample_information_circos.png'),1760,1758,res=220,bg='white');circos.clear();circos.par(start.degree=90,gap.after=c(rep(.25,n-1),82),cell.padding=c(0,0,0,0),track.margin=c(.003,.003),points.overflow.warning=F);circos.initialize(d53$id,xlim=c(.5,1.5));tn<-function(v,col,yl){circos.trackPlotRegion(ylim=yl,track.height=.16,bg.border='#222',bg.lwd=.55,panel.fun=function(x,y){i<-CELL_META$sector.numeric.index;circos.lines(c(.65,1.35),rep(v[i],2),col=col,lwd=1.4);circos.points(1,v[i],pch=16,cex=.35,col=col)})};tc<-function(v,p){circos.trackPlotRegion(ylim=c(0,1),track.height=.075,bg.border='#222',bg.lwd=.5,panel.fun=function(x,y){i<-CELL_META$sector.numeric.index;circos.rect(.5,0,1.5,1,col=p[v[i]],border=NA)})};tn(d53$age,'#631879',c(15,82));tn(d53$BMI,'#FF410D',c(15,42));tc(d53$sex,c(Female='#F2300F',Male='#E1BD6D'));tc(d53$ethnicity,c(Caucasian='#ECCBAE',Asian='#0B775E',Hispanic='#D69C4E',Black='#81A88D'));tc(d53$IRIS,c(IS='#F21A00',IR='#74A089'));circos.trackPlotRegion(ylim=c(0,1),track.height=.07,bg.border=NA,panel.fun=function(x,y)circos.text(1,.5,CELL_META$sector.index,facing='clockwise',niceFacing=T,cex=.28));circos.clear();dev.off();f53<-file.path(fd,'53_sample_information_circos.png');side_num<-function(v,col,title)ggplot(data.frame(x=1,y=v),aes(x,y))+geom_boxplot(outlier.shape=NA,width=.35,linewidth=.45)+geom_jitter(width=.12,size=.65,colour=col,alpha=.75)+labs(title=title)+theme_bw(base_size=6)+theme(panel.grid=element_blank(),axis.title=element_blank(),axis.text.x=element_blank(),axis.ticks.x=element_blank(),panel.border=element_rect(colour='#222',linewidth=.5));side_cat<-function(v,pal,title)ggplot(data.frame(x=title,v=v),aes(x,fill=v))+geom_bar(width=.72,colour='#222',linewidth=.4)+scale_fill_manual(values=pal)+theme_bw(base_size=6)+theme(panel.grid=element_blank(),axis.title=element_blank(),axis.text.x=element_blank(),legend.position='none',panel.border=element_rect(colour='#222',linewidth=.5));ps53<-(side_num(d53$age,'#631879','Age')/side_num(d53$BMI,'#FF410D','BMI')/side_cat(d53$sex,c(Female='#F2300F',Male='#E1BD6D'),'Gender')/side_cat(d53$ethnicity,c(Caucasian='#ECCBAE',Asian='#0B775E',Hispanic='#D69C4E',Black='#81A88D'),'Ethnicity')/side_cat(d53$IRIS,c(IS='#F21A00',IR='#74A089'),'IRIS'))+plot_layout(heights=c(1.6,1.6,.78,.78,.78));tmp53<-file.path(root,'work','cases-46-55','53_side.png');dir.create(dirname(tmp53),recursive=TRUE,showWarnings=FALSE);ggsave(tmp53,ps53,width=1.75,height=6,dpi=220,bg='white');left53<-magick::image_resize(magick::image_read(tmp53),'385x1500!');ring53<-magick::image_resize(magick::image_read(f53),'1800x1800');canvas53<-magick::image_extent(ring53,'1760x1758',gravity='east',color='white');final53<-magick::image_composite(canvas53,left53,offset='+45+100',operator='over');magick::image_write(final53,f53);wd('53_sample_information_circos.csv',d53)
# 54 composition + dumbbell
f<-c('Serranidae','Zoarcidae','Myctophidae','Sebastidae','Liparidae','Carangidae','Macrouridae','Nototheniidae','Psychrolutidae','Scorpaenidae','Paralichthyidae','Pleuronectidae','Soleidae','Stomiidae','Ophidiidae','Lutjanidae','Moridae','Monacanthidae','Gobiidae','Ophichthidae','Parapercidae','Sparidae','Muraenidae','Pomacentridae','Syngnathidae');d54<-data.frame(family=f,med=seq(8,32,length.out=length(f))+rnorm(length(f),0,2));d54$lo<-pmax(0,d54$med-runif(nrow(d54),4,9));d54$hi<-d54$med+runif(nrow(d54),5,13);d54$obs<-pmax(0,d54$med+rnorm(nrow(d54),0,8));d54$class<-ifelse(d54$obs>d54$hi,'Above expectation',ifelse(d54$obs<d54$lo,'Below expectation','Within expectation'));d54$family<-factor(d54$family,levels=rev(d54$family));d54b<-expand.grid(family=levels(d54$family),depth=c('Deep','Intermediate','Shallow'));d54b$n<-runif(nrow(d54b));d54b$family<-factor(d54b$family,levels=levels(d54$family));p1<-ggplot(d54b,aes(family,n,fill=depth))+geom_col(position='fill',width=.68)+coord_flip()+scale_fill_manual(values=c(Deep='#6946A6',Intermediate='#A178DF',Shallow='#DCB0FF'))+theme_classic(base_size=6)+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_blank(),legend.position='bottom',legend.title=element_blank())+labs(x=NULL,y=NULL);p2<-ggplot(d54,aes(family,obs))+geom_segment(aes(y=lo,yend=hi,xend=family),colour='grey82',linewidth=3,lineend='round')+geom_segment(aes(y=med,yend=obs,xend=family),colour='grey45',linewidth=.55)+geom_point(aes(y=med),shape=21,fill='white',colour='grey35',size=2.6,stroke=.8)+geom_point(aes(colour=class),size=2.9)+coord_flip()+scale_colour_manual(values=c('Above expectation'='#D65DB1','Within expectation'='grey35','Below expectation'='#F2AD00'))+labs(x=NULL,y='Number of Transitions',colour=NULL)+theme_classic(base_size=7)+dark+theme(axis.text.y=element_blank(),axis.line.y=element_blank(),axis.ticks.y=element_blank(),panel.grid.major.y=element_line(colour='grey82',linewidth=.35),legend.position='bottom',legend.background=element_rect(fill='white',colour='#666',linewidth=.45));sv('54_stacked_bar_dumbbell.png',p1+p2+plot_layout(widths=c(1,4.3)),5,8);wd('54_dumbbell.csv',d54);wd('54_depth.csv',d54b)
# 55 dual-triangle ComplexHeatmap
n<-46;nm<-paste0(sample(c('Ab','Alb','AP','ATP','BA','CD','ER','GST','IFN','IL','MIP','N','PP','PPO','TR'),n,T),'_',1:n);a<-matrix(rnorm(n*n,0,.45),n);a<-(a+t(a))/2;b<-matrix(rnorm(n*n,0,.45),n);b<-(b+t(b))/2;diag(a)<-diag(b)<-1;m<-a;for(i in 1:n)m[i,1:i]<-b[i,1:i];rownames(m)<-colnames(m)<-nm;cl<-colorRamp2(c(-1,0,1),c('#F6E213','white','#801B9C'));cr<-colorRamp2(c(-1,0,1),c('#75C500','white','#E43A21'));png(file.path(fd,'55_dual_triangle_circle_heatmap.png'),1617,1760,res=220,bg='white');h<-Heatmap(m,rect_gp=gpar(type='none'),show_heatmap_legend=F,cluster_rows=F,cluster_columns=F,row_names_gp=gpar(fontsize=4.8),column_names_gp=gpar(fontsize=4.8),column_names_rot=75,cell_fun=function(j,i,x,y,w,h,fill){grid.rect(x,y,w,h,gp=gpar(col='#777',fill=NA,lwd=.52));v<-m[i,j];grid.circle(x,y,r=sqrt(abs(v))*.46*min(unit.c(w,h)),gp=gpar(fill=if(i>=j)cl(v)else cr(v),col=NA))});draw(h,annotation_legend_list=list(Legend(col_fun=cl,title='M0',direction='horizontal'),Legend(col_fun=cr,title='M1',direction='horizontal')),annotation_legend_side='bottom');dev.off();wd('55_dual_triangle_circle_heatmap.csv',data.frame(row=rep(nm,n),column=rep(nm,each=n),correlation=as.vector(m)))
message('Rendered source-method studies 46-55')
